  "effect:splat-exploration": { d: "Stylizes a Gaussian splat clip by layering the splat with stretched light streaks, drifting particles and a wireframe surface mesh.", t: ["gaussian splat", "3d scan", "particles", "wireframe", "point cloud"] },
