  "effect:tone-geometry": { d: "Replaces the image with a grid of squares, circles or triangles sized by darkness, in Ink on Paper; Shape picks the form, Scale the cell size.", t: ["geometric halftone", "shapes", "dots", "pattern", "grid"] },
