  "tracking.anchors": { d: "Picks the face landmark positions used as cable start and end points, such as mouth corners, irises or brows.", t: ["attachment points", "anchor", "landmarks", "cable ends"] },
  "tracking.face": { d: "Detects the face in each video frame with MediaPipe and outputs its landmark points for cables and face meshes.", t: ["face tracking", "landmarks", "mediapipe", "face detection", "facial points"] },
  "values.number": { d: "Outputs a fixed number you set with Value, for driving node inputs or parameters.", t: ["constant", "number", "value", "scalar", "float"] },
  "values.oscillator": { d: "Outputs a sine wave over time, Offset + Amplitude × sin(time × Frequency), for pulsing or swinging values.", t: ["lfo", "sine", "wave", "oscillate", "pulse", "wobble"] },
  "vector.combine.vec2": { t: ["make vector", "join xy", "compose", "pack"] },
